        dibujarCorazones();
        dibujarEscudos();
        dibujarCanones();
        dibujarEnemigos();
        dibujarJefe();
        dibujarProyectiles();
        dibujarJugador();
        dibujarParticulas();

        ctx.restore();

        dibujarHUD();
        dibujarIndicadorLlave();
